import { createHash } from 'node:crypto';
import { mkdir, readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const binary = path.join(
  root,
  'native',
  'windows-job-wrapper',
  'bin',
  'windows-x64',
  'codex-infinite-job-wrapper.exe',
);
const target = path.join(root, 'src', 'generated', 'windows-job-wrapper-integrity.ts');
const digest = createHash('sha256').update(await readFile(binary)).digest('hex');
const content = [
  '// Generated by scripts/generate-native-integrity.mjs. Do not edit manually.',
  `export const WINDOWS_JOB_WRAPPER_SHA256 = '${digest}';`,
  '',
].join('\n');

await mkdir(path.dirname(target), { recursive: true });
const current = await readFile(target, 'utf8').catch(() => null);
if (current !== content) await writeFile(target, content, { encoding: 'utf8', mode: 0o600 });
